import React from "react"
import { graphql, PageProps } from "gatsby"
import { Camera } from "@phosphor-icons/react"
import Layout from "../components/layout"
import SEO from "../components/seo"
import { IconWrapper } from "../components/icons"
import { Reveal } from "../components/animations"
import { PhotoGallery, toPhotoItem } from "../components/photos"
import type { PhotoItem, PhotoNode } from "../components/photos"

interface PhotosPageData {
  site: {
    siteMetadata: {
      title: string
    }
  }
  allMarkdownRemark: {
    nodes: PhotoNode[]
  }
}

const PhotosPage: React.FC<PageProps<PhotosPageData>> = ({
  data,
  location,
}) => {
  const siteTitle = data.site.siteMetadata.title
  const photos = data.allMarkdownRemark.nodes
    .map(toPhotoItem)
    .filter((p): p is PhotoItem => p !== null)
  const totalImages = photos.reduce((sum, p) => sum + p.images.length, 0)

  return (
    <Layout location={location} title={siteTitle}>
      <SEO
        title="照片"
        description="快门里的碎片：路过的地方与光线"
        keywords={["照片", "photos", "摄影", "gallery"]}
      />

      <header className="mb-8 text-center fade-in">
        <div className="inline-flex items-center justify-center w-12 h-12 rounded-xl bg-accent-subtle mb-3">
          <IconWrapper icon={Camera} size={24} className="text-accent" />
        </div>
        <h1 className="text-2xl font-bold text-foreground mb-2 font-serif">
          照片
        </h1>
        <p className="text-foreground-secondary text-sm max-w-md mx-auto">
          快门里的碎片，共{" "}
          <span className="text-accent font-semibold">{totalImages}</span> 张
        </p>
      </header>

      {photos.length === 0 ? (
        <div className="text-center py-16 fade-in">
          <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-background-secondary mb-3">
            <IconWrapper
              icon={Camera}
              size={32}
              className="text-foreground-muted"
            />
          </div>
          <p className="text-foreground-secondary text-sm">暂无照片</p>
        </div>
      ) : (
        <Reveal>
          <PhotoGallery photos={photos} />
        </Reveal>
      )}
    </Layout>
  )
}

export default PhotosPage

export const pageQuery = graphql`
  query {
    site {
      siteMetadata {
        title
      }
    }
    allMarkdownRemark(
      sort: { frontmatter: { date: DESC } }
      filter: { fileAbsolutePath: { regex: "/content/photos/" } }
    ) {
      nodes {
        frontmatter {
          title
          note
          photos {
            src {
              childImageSharp {
                gatsbyImageData(
                  width: 800
                  placeholder: BLURRED
                  formats: [AUTO, WEBP]
                )
              }
            }
            note
            featured
            position
          }
        }
        parent {
          ... on File {
            relativeDirectory
          }
        }
      }
    }
  }
`
